 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            vals = [grid[i][j] for i in range(r, min(r+3,h)) for j in range(c, min(c+3,w)) if grid[i][j] not in (0, 5)]
            row.append(max(set(vals), key=vals.count) if vals else 0)
        out.append(row)
    return out
